-- The brush cards use actual strokes generated by the Inkora C++ raster
-- pipeline. Preview images are cached, not repainted on every UI frame.
local Brush=require("src.brush")
local Native=require("src.native")
local Preview={}
local cache={}
local WIDTH,HEIGHT=168,44

local function idFor(preset,mask)
    return preset.id..":"..(mask and tostring(mask.buffer) or "default")
end

function Preview.get(preset,customMask)
    if not preset then return nil end
    if preset.tip==3 and not customMask then return nil end
    if not Native.available() then return nil end
    local key=idFor(preset,customMask)
    if cache[key] then return cache[key] end

    local canvas=love.graphics.newCanvas(WIDTH,HEIGHT,{format="rgba8"})
    love.graphics.push("all")
    love.graphics.setCanvas(canvas)
    love.graphics.clear(0,0,0,0)
    love.graphics.pop()
    Native.registerBlank(canvas)

    local session=Brush.beginStroke(canvas,{
        hardness=preset.hardness,spacing=preset.spacing,
        tip=preset.tip,aspect=0.3,angle=preset.tip==3 and 0 or 25,
        grain=0.85,seed=239,
        mask=preset.tip==3 and customMask or nil,
        flow=preset.flow,pressureOpacity=preset.pressureOpacity
    })
    assert(session,"Falha ao criar preview no motor C++")

    local diameter=math.min(20,math.max(3,preset.size*0.6))
    local ink={0.28,0.73,0.93}
    local points=23
    local lastX,lastY=9,24
    local lastPressure=0.5
    Brush.segment(canvas,lastX,lastY,lastX,lastY,ink,
        diameter,preset.opacity,false,session,lastPressure,lastPressure)
    for i=1,points do
        local t=i/points
        local x=9+148*t
        local y=23+math.sin(t*math.pi*2.0)*7
        local pressure=0.45+0.5*math.sin(t*math.pi)^2
        Brush.segment(canvas,lastX,lastY,x,y,ink,
            diameter,preset.opacity,false,session,lastPressure,pressure)
        lastX,lastY,lastPressure=x,y,pressure
    end
    cache[key]=canvas
    return canvas
end

function Preview.invalidate(id)
    if not id then cache={} return end
    for key in pairs(cache) do
        if key:sub(1,#id+1)==id..":" then cache[key]=nil end
    end
end

function Preview.stats()
    local count=0
    for _ in pairs(cache) do count=count+1 end
    return {count=count,width=WIDTH,height=HEIGHT}
end

return Preview
